'use strict';
// Fixtures are generated by test/fixtures/make_fixtures.py.
const test = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');
const HT = require('../lib/docx.js');

const fixture = (name) => fs.readFileSync(path.join(__dirname, 'fixtures', name));
const para = (runs, extra) => ({
  type: 'paragraph',
  style: 'normal',
  list: null,
  align: 'left',
  runs,
  ...extra,
});
const text = (p) => p.runs.map((r) => r.text).join('');

let sample;
test.before(async () => {
  sample = await HT.parseDocx(fixture('sample-deflate.docx'));
});
// The paragraph whose text starts with `prefix`.
const find = (prefix) => {
  const p = sample.doc.blocks.find((b) => b.type === 'paragraph' && text(b).startsWith(prefix));
  assert.ok(p, `paragraph starting with "${prefix}" not found`);
  return p;
};

test('the parsed document satisfies the shared model', () => {
  assert.deepStrictEqual(HT.validate(sample.doc), []);
  assert.deepStrictEqual(HT.normalize(sample.doc), sample.doc);
});

test('title, subtitle and headings (style names, localized ids, basedOn, outline level)', () => {
  const styles = sample.doc.blocks.slice(0, 6).map((b) => [b.style, text(b)]);
  assert.deepStrictEqual(styles, [
    ['title', 'İstanbul Çalışma Günlüğü'],
    ['subtitle', 'A subtitle'],
    ['h1', 'Giriş'],
    ['h2', 'Second level'],
    ['h2', 'Based on heading two'],
    ['h3', 'Outline level three'],
  ]);
});

test('heading text does not inherit bold from the heading style', () => {
  assert.deepStrictEqual(find('Giriş').runs, [{ text: 'Giriş' }]);
});

test('bold, italic, underline and strike runs; equal neighbours are merged', () => {
  assert.deepStrictEqual(find('plain').runs, [
    { text: 'plain still plain ' },
    { text: 'bold', bold: true },
    { text: ' ' },
    { text: 'italic', italic: true },
    { text: ' ' },
    { text: 'underline', underline: true },
    { text: ' ' },
    { text: 'strike', strike: true },
    { text: ' ' },
    { text: 'all', bold: true, italic: true, underline: true, strike: true },
  ]);
});

test('w:val="0" / "false" / "none" switch a property off', () => {
  assert.deepStrictEqual(find('off').runs, [{ text: 'off' }]);
});

test('run properties are inherited from paragraph and character styles', () => {
  assert.deepStrictEqual(find('loud').runs, [
    { text: 'loud ', bold: true, italic: true },
    { text: 'quiet', italic: true },
  ]);
  assert.deepStrictEqual(find('strong').runs, [{ text: 'strong', bold: true }, { text: ' text' }]);
});

test('Turkish characters and XML entities are decoded', () => {
  assert.strictEqual(text(find('ığ')), 'ığüşöçİĞÜŞÖÇ');
  assert.strictEqual(text(find('Tom')), 'Tom & Jerry <tag> "q" \'a\' café ığ 😀');
});

test('alignment from w:jc, directly and through the style', () => {
  assert.strictEqual(find('İstanbul').align, 'center');
  assert.strictEqual(find('centered').align, 'center');
  assert.strictEqual(find('right').align, 'right');
  assert.strictEqual(find('justified').align, 'justify');
  assert.strictEqual(find('centered by style').align, 'center');
  assert.strictEqual(find('plain').align, 'left');
});

test('bullet and numbered lists with nesting', () => {
  const lists = ['bullet zero', 'bullet one', 'bullet two', 'number zero', 'number one', 'bullet by style', 'not a list'];
  assert.deepStrictEqual(
    lists.map((t) => find(t).list),
    [
      { kind: 'bullet', level: 0 },
      { kind: 'bullet', level: 1 },
      { kind: 'bullet', level: 2 },
      { kind: 'number', level: 0 },
      { kind: 'number', level: 1 },
      { kind: 'bullet', level: 0 },
      null,
    ]
  );
});

test('line breaks split the paragraph, tabs become spaces', () => {
  const i = sample.doc.blocks.indexOf(find('first line'));
  assert.deepStrictEqual(sample.doc.blocks.slice(i, i + 3), [
    para([{ text: 'first line' }], { align: 'center' }),
    para([{ text: 'second line' }], { align: 'center' }),
    para([{ text: 'third line' }], { align: 'center' }),
  ]);
});

test('hyperlinks become plain runs with their visible text', () => {
  assert.deepStrictEqual(find('See').runs, [{ text: 'See the site now' }]);
});

test('table with merged cells stays rectangular; nested table is flattened', () => {
  const tables = sample.doc.blocks.filter((b) => b.type === 'table');
  assert.strictEqual(tables.length, 1);
  const rows = tables[0].rows;
  assert.deepStrictEqual(rows.map((r) => r.length), [3, 3, 3]);
  const cellTexts = rows.map((r) => r.map((c) => c.paragraphs.map(text)));
  assert.deepStrictEqual(cellTexts, [
    [['Wide'], [''], ['C1']],
    [['Tall'], ['B2'], ['C2']],
    [[''], ['B3', 'inner one', 'inner two', ''], ['C3a', 'C3b']],
  ]);
  assert.deepStrictEqual(rows[1][2].paragraphs[0].runs, [{ text: 'C2', bold: true }]);
  assert.strictEqual(
    HT.toPlainText({ blocks: tables }),
    'Wide\t\tC1\nTall\tB2\tC2\n\tB3 inner one inner two \tC3a C3b'
  );
});

test('images, text boxes, footnotes and comments are skipped with warnings', () => {
  assert.deepStrictEqual(find('before').runs, [{ text: 'before after' }]);
  assert.ok(!HT.toPlainText(sample.doc).includes('boxed'));
  assert.deepStrictEqual(sample.warnings, [
    '2 images skipped',
    '1 text box skipped',
    '1 footnote skipped',
    '1 comment skipped',
    '1 nested table flattened to text',
    '2 merged cells expanded',
    'Headers and footers skipped',
  ]);
});

test('tracked deletions are dropped and insertions kept', () => {
  assert.strictEqual(text(find('kept')), 'kept inserted');
});

test('XML comments, CDATA and ">" inside attribute values are handled', () => {
  assert.strictEqual(text(find('cdata')), 'cdata <text>');
});

test('stats and plain text of the sample', () => {
  const s = HT.stats(sample.doc);
  assert.strictEqual(s.tables, 1);
  assert.strictEqual(s.blocks, s.paragraphs + s.tables);
  assert.strictEqual(s.blocks, sample.doc.blocks.length);
  assert.ok(HT.toPlainText(sample.doc).startsWith('İstanbul Çalışma Günlüğü\nA subtitle\nGiriş\n'));
});

test('a stored (uncompressed) archive gives the same result as a deflated one', async () => {
  const zip = HT.readZip(fixture('sample-stored.docx'));
  assert.ok(zip.names.includes('word/document.xml'));
  const xml = new TextDecoder().decode(await zip.read('word/document.xml'));
  assert.ok(xml.includes('<w:body>'));
  assert.deepStrictEqual(await HT.parseDocx(fixture('sample-stored.docx')), sample);
});

test('accepts ArrayBuffer, Uint8Array and offset views', async () => {
  const buf = fixture('sample-deflate.docx');
  const arrayBuffer = buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength);
  assert.deepStrictEqual(await HT.parseDocx(arrayBuffer), sample);
  const padded = new Uint8Array(buf.length + 7);
  padded.set(buf, 7);
  assert.deepStrictEqual(await HT.parseDocx(padded.subarray(7)), sample);
  assert.deepStrictEqual(await HT.parseFile('Sample.DOCX', arrayBuffer), sample);
});

test('without styles.xml and numbering.xml, style ids and list defaults are used', async () => {
  const { doc, warnings } = await HT.parseDocx(fixture('minimal.docx'));
  assert.deepStrictEqual(warnings, []);
  assert.deepStrictEqual(doc.blocks, [
    para([{ text: 'Heading by id' }], { style: 'h1' }),
    para([{ text: 'Title by id' }], { style: 'title' }),
    para([{ text: 'unknown list' }], { list: { kind: 'bullet', level: 1 } }),
    para([{ text: 'body' }]),
  ]);
});

test('non-zip, truncated and corrupt files reject with a clean Error', async () => {
  const isError = (re) => (e) => e instanceof Error && re.test(e.message);
  const good = fixture('sample-deflate.docx');
  await assert.rejects(HT.parseDocx(Buffer.from('this is not a zip file at all')), isError(/Not a ZIP archive/));
  await assert.rejects(HT.parseDocx(new ArrayBuffer(0)), isError(/Not a ZIP archive/));
  await assert.rejects(HT.parseDocx(good.subarray(0, good.length >> 1)), isError(/Not a ZIP archive/));
  // Keep the directory at the end but cut bytes from the front: offsets no longer match.
  await assert.rejects(HT.parseDocx(good.subarray(100)), isError(/Corrupt ZIP archive/));
  await assert.rejects(HT.parseDocx(fixture('bad-deflate.docx')), isError(/Corrupt ZIP archive.*document\.xml/));
  await assert.rejects(HT.parseDocx(fixture('no-document.docx')), isError(/Not a Word document/));
  await assert.rejects(HT.parseDocx('a string'), (e) => e instanceof Error);
  await assert.rejects(HT.parseFile('x.docx', Buffer.from('nope')), isError(/Not a ZIP archive/));
});
